<?php use VoiceShop\Domain\StatusFlow; ?>
<div class="heading"><div><p class="eyebrow">OWNER WORKSPACE</p><h1>Your order desk</h1><p>Review details. Confirm when you're ready.</p></div><a class="button" href="import.php">+ Import order</a></div>
<div class="sections"><?php foreach ($sections as $label => $rows): ?><section><h2><?= $e($label) ?> <span class="count"><?= count($rows) ?></span></h2><?php if (!$rows): ?><p class="empty">No orders here yet.</p><?php endif ?><?php foreach ($rows as $o): ?><a class="card" href="index.php?page=detail&id=<?= (int)$o['id'] ?>"><div class="row"><strong>#<?= (int)$o['id'] ?></strong><span class="badge <?= $e($o['status']) ?>"><?= $e(StatusFlow::label($o['status'])) ?></span></div><h3><?= $e($o['customer_name'] ?: 'Name missing') ?></h3><p><?= $e($o['shop_name']) ?></p><div class="row muted"><span><?= (int)$o['item_count'] ?> items</span><time><?= $e($o['created_at']) ?></time></div><?php if ($o['missing_count']): ?><span class="chip"><?= (int)$o['missing_count'] ?> missing details</span><?php endif ?><?php if ($o['is_demo']): ?><span class="chip">Demo data</span><?php endif ?></a><?php endforeach ?></section><?php endforeach ?></div>
